<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class GoodsReceipt extends Model { use HasUuids; protected $table = 'goods_receipts'; protected $fillable = ['tenant_id', 'company_id', 'branch_id', 'warehouse_id', 'purchase_order_id', 'received_by', 'posted_by', 'number', 'receipt_date', 'supplier_delivery_number', 'reference_number', 'receiving_notes', 'state', 'idempotency_key', 'posted_at', 'reversed_at', 'reversed_by', 'reversal_reason']; protected function casts(): array { return ['receipt_date' => 'date', 'posted_at' => 'datetime', 'reversed_at' => 'datetime']; } public function items() { return $this->hasMany(GoodsReceiptItem::class); } public function purchaseOrder() { return $this->belongsTo(PurchaseOrder::class); } public function receivedBy() { return $this->belongsTo(User::class, 'received_by'); } public function postedBy() { return $this->belongsTo(User::class, 'posted_by'); } public function company() { return $this->belongsTo(Company::class); } public function branch() { return $this->belongsTo(Branch::class); } public function warehouse() { return $this->belongsTo(Warehouse::class); } }
